<template><view class="group-size-setting"><Bi :zh="zh" :fr="fr" small/><view ref="bar" :class="['group-size-slider',{dragging,adjusting:showValue}]" role="slider" tabindex="0" aria-valuemin="3" aria-valuemax="15" :aria-valuenow="Math.round(visual)" :aria-valuetext="Math.round(visual)+' / 15'" :aria-label="zh+' / '+fr" :aria-disabled="disabled" :style="{'--position':((visual-3)/12*100)+'%'}"><text class="group-size-value">{{ Math.round(visual) }}</text><view class="group-size-track"><view class="group-size-fill"/></view><view class="group-size-thumb"/></view></view></template>
<script setup>
import {ref,watch,onMounted,onUnmounted} from 'vue';import Bi from './Bi.vue';import {groupSize} from '../domain/group-size.js';
const props=defineProps({value:Number,zh:String,fr:String,disabled:Boolean}),emit=defineEmits(['change']),visual=ref(groupSize(props.value)),bar=ref(null),dragging=ref(false),showValue=ref(false);let frame,rect,pointer,el,keyTarget;
function animateTo(value){cancelAnimationFrame(frame);if(window.matchMedia?.('(prefers-reduced-motion: reduce)').matches){visual.value=groupSize(value);return;}const from=visual.value,to=groupSize(value),start=performance.now();const step=now=>{const t=Math.min(1,(now-start)/180),ease=1-(1-t)**3;visual.value=from+(to-from)*ease;if(t<1)frame=requestAnimationFrame(step);};frame=requestAnimationFrame(step);}
function update(e){if(!rect?.width)return;const ratio=Math.max(0,Math.min(1,(e.clientX-rect.left)/rect.width));visual.value=3+ratio*12;}
function down(e){if(props.disabled||e.button!==0||e.isPrimary===false||dragging.value)return;e.preventDefault();cancelAnimationFrame(frame);rect=el.getBoundingClientRect();pointer=e.pointerId;dragging.value=true;showValue.value=true;el.setPointerCapture?.(pointer);update(e);}
function move(e){if(dragging.value&&e.pointerId===pointer){e.preventDefault();update(e);}}
function endPointer(save){if(!dragging.value)return;dragging.value=false;showValue.value=false;const id=pointer;pointer=null;try{el.releasePointerCapture?.(id);}catch{}if(!save)animateTo(props.value);else{const next=groupSize(visual.value);animateTo(next);emit('change',next);}}
function up(e){if(!dragging.value||e.pointerId!==pointer)return;if(e.type==='pointerup')update(e);endPointer(e.type==='pointerup');}
function key(e){if(props.disabled||dragging.value)return;const delta={ArrowLeft:-1,ArrowDown:-1,ArrowRight:1,ArrowUp:1}[e.key];if(delta||['Home','End'].includes(e.key)){e.preventDefault();const next=e.key==='Home'?3:e.key==='End'?15:groupSize((keyTarget??Math.round(visual.value))+delta);keyTarget=next;showValue.value=true;animateTo(next);emit('change',next);}}
function keyup(e){if(['ArrowLeft','ArrowDown','ArrowRight','ArrowUp','Home','End'].includes(e.key)){showValue.value=false;keyTarget=undefined;}}
function cancel(){endPointer(false);showValue.value=false;keyTarget=undefined;}
function hide(){if(document.hidden)cancel();}
watch(()=>props.value,value=>{if(!dragging.value)animateTo(value);});watch(()=>props.disabled,disabled=>{if(!disabled&&!dragging.value&&Math.round(visual.value)!==groupSize(props.value))animateTo(props.value);});
onMounted(()=>{el=bar.value?.$el||bar.value;el.addEventListener('pointerdown',down);el.addEventListener('pointermove',move);el.addEventListener('pointerup',up);el.addEventListener('pointercancel',up);el.addEventListener('keydown',key);el.addEventListener('keyup',keyup);el.addEventListener('lostpointercapture',cancel);el.addEventListener('blur',cancel);window.addEventListener('blur',cancel);document.addEventListener('visibilitychange',hide);});
onUnmounted(()=>{cancelAnimationFrame(frame);if(el){el.removeEventListener('pointerdown',down);el.removeEventListener('pointermove',move);el.removeEventListener('pointerup',up);el.removeEventListener('pointercancel',up);el.removeEventListener('keydown',key);el.removeEventListener('keyup',keyup);el.removeEventListener('lostpointercapture',cancel);el.removeEventListener('blur',cancel);}window.removeEventListener('blur',cancel);document.removeEventListener('visibilitychange',hide);});
</script>
<style scoped>.group-size-setting{padding:18px 0 10px}.group-size-slider{position:relative;height:78px;margin:14px 12px 0;touch-action:none;user-select:none;outline-offset:4px}.group-size-track{position:absolute;top:35px;left:0;right:0;height:14px;border-radius:14px;background:var(--theme-border,#d6e0ef);box-shadow:inset 0 1px 2px #53688d18}.group-size-fill{height:100%;width:var(--position);background:linear-gradient(90deg,var(--accent),var(--accent-dark,var(--accent)));border-radius:inherit}.group-size-thumb{position:absolute;left:var(--position);top:26px;width:32px;height:32px;margin-left:-16px;border-radius:50%;background:#fff;border:2px solid var(--accent);box-shadow:0 3px 10px #394c6d35;will-change:left}.group-size-value{position:absolute;left:var(--position);top:-3px;z-index:1;transform:translate(-50%,4px) scale(.92);transform-origin:center bottom;padding:4px 9px;border-radius:11px;background:var(--accent);color:#fff;font-size:15px;font-weight:700;line-height:1.2;font-variant-numeric:tabular-nums;box-shadow:0 4px 11px #394c6d25;opacity:0;pointer-events:none;transition:opacity .12s,transform .16s cubic-bezier(.2,.7,.3,1)}.group-size-slider.adjusting .group-size-value{opacity:1;transform:translate(-50%,0) scale(1)}.group-size-slider:focus-visible{border-radius:12px;outline:3px solid #a4b2e3;outline-offset:5px}@media(prefers-reduced-motion:reduce){.group-size-value{transition:none}.group-size-thumb{will-change:auto}}</style>
